  const borderProgress = spring({
    frame: frame - startFrame,
    fps,
    config: { damping: 200, stiffness: 100, mass: 2 },
    durationInFrames: borderDur
  });
  
  // Outer Border Path Length approx
  const perimeter = (cardWidth + cardHeight) * 2;
  const dashOffset = interpolate(borderProgress, [0, 1], [perimeter, 0]);

  // --- Animation: Title ---
  const titleSpring = spring({
    frame: frame - startFrame - textDelay,
    fps,
    config: { damping: 15 }
  });
  
  const titleScale = interpolate(titleSpring, [0, 1], [0.8, 1]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);
  const titleY = interpolate(titleSpring, [0, 1], [50, 0]);

  // --- Animation: Subtitles ---
  const sub1Progress = spring({
    frame: frame - startFrame - textDelay - 15,
    fps,
    config: { damping: 15 }
  });
  
